using System;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
public static class MotionParityInstall {
 public static void Run(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");var scene=EditorSceneManager.OpenScene(TrainingFlowSession.TrainingScene);var actors=UnityEngine.Object.FindObjectsByType<TrainingFighter>(FindObjectsSortMode.None);if(actors.Length!=2)throw new Exception("Expected two fighters");var source=actors.Select(a=>a.GetComponent<ApprovedLocomotionTuning>()).Single(t=>t!=null);if(!PrefabUtility.IsAddedComponentOverride(source)||source.canonicalProfile==null||!source.canonicalProfile.TryRead(out var settings,out var error))throw new Exception("Expected adopted player-only component override");string profile=AssetDatabase.GetAssetPath(source.canonicalProfile);if(profile!="Assets/Shioka/調整Data/Fighter/Awari/Move/ApprovedLocomotionProfile.asset"||source.loadSavedDraftOnStart)throw new Exception("Unexpected canonical/draft source");foreach(var a in actors)Debug.Log("PARITY_BEFORE "+a.name+" raw="+JsonUtility.ToJson(a.definition)+" canonical="+(a.GetComponent<ApprovedLocomotionTuning>()!=null));PrefabUtility.ApplyAddedComponent(source,"Assets/Shioka/調整Data/Fighter/Awari/Awari.prefab",InteractionMode.AutomatedAction);foreach(var a in actors){var all=a.GetComponents<ApprovedLocomotionTuning>();if(all.Length!=1||all[0].canonicalProfile==null||AssetDatabase.GetAssetPath(all[0].canonicalProfile)!=profile||all[0].loadSavedDraftOnStart)throw new Exception("Shared prefab consumer not inherited exactly once");if(PrefabUtility.IsAddedComponentOverride(all[0]))throw new Exception("Scene-only tuning remains");}EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Debug.Log("PARITY_INSTALL shared adopted profile via Awari prefab; values unchanged: "+JsonUtility.ToJson(settings));}
}
